local Translate = ns.Lore.Translate

Translate("frFR", "stranglethorn-vale", {
	title = "Vallée de Strangleronce",
	aliases = { "Strangleronce", "la Vallée" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Vallée de Strangleronce est la grande jungle du sud. Elle s'étend des sombres confins du {link:duskwood}Bois de la Pénombre{/link} jusqu'à un cap rocheux où la terre finit dans la mer. Ses arbres sont vieux et hauts, ses rivières grouillent de crocilisques, et tigres, panthères, raptors et grands singes chassent sous sa voûte verte. Partout, les lianes ont avalé les pierres d'un empire troll déchu. Aucune couronne ne règne ici. Les gobelins tiennent le port de {link:booty-bay}Baie-du-Butin{/link}, la {link:horde}Horde{/link} garde un camp sur la côte ouest, les chasseurs et les déserteurs du nord plantent leurs tentes dans les collines, et les tribus trolls mènent leurs vieilles guerres dans les ruines de leurs pères.]=],
		},
		{
			title = "Origines",
			text = [=[Ce fut jadis le cœur des Gurubashi, les trolls de la jungle du sud. Aux âges d'avant la {link:great-sundering}Grande Fracture{/link}, leur empire s'étendait sur ces terres et bien au-delà. Quand le monde se brisa, l'empire perdit une grande part de ses terres au profit de la mer, et son peuple, dans sa détresse, se tourna vers un culte sombre. Les prêtres atal'ai appelèrent {link:hakkar}Hakkar{/link}, le dieu du sang, dans leur capitale de {link:zul-gurub}Zul’Gurub{/link}. Le dieu se nourrit de ses fidèles, et les tribus finirent par se dresser contre lui et contre ses prêtres. Elles chassèrent Hakkar et repoussèrent les Atal'ai dans les marais du nord. L'empire gurubashi ne s'en releva jamais. Ses tribus se retournèrent les unes contre les autres, et les cités qu'elles avaient bâties furent abandonnées à la jungle.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Strangleronce n'a pas de maître, et elle en a donc beaucoup. Les gobelins du {link:steamwheedle-cartel}Cartel Gentepression{/link} règnent sur {link:booty-bay}Baie-du-Butin{/link}, à la pointe sud, où tout pavillon est bienvenu tant qu'il paie. Les pirates de deux flottes rivales, les {red:blackwater-raiders}Blackwater Raiders{/red} et la {red:bloodsail-buccaneers}Voile sanglante{/red}, se disputent les eaux du cap. La {link:venture-company}KapitalRisk{/link} dépouille les collines du nord de leur bois et de leurs cristaux. Au nord, une troupe de soldats de {link:stormwind-city}Stormwind{/link} mène une guerre désespérée contre son ancien colonel. Sur la côte ouest, la {link:horde}Horde{/link} a élevé {link:grom-gol-base-camp}Grom'gol{/link}, et ses émissaires {link:darkspear-trolls}Darkspear{/link} sont revenus au pays chercher un fils perdu de leur tribu. Le célèbre chasseur {link:hemet-nesingwary}Hemet Nesingwary{/link} est venu traquer les grands fauves de la jungle. Et derrière tout cela, les trolls perdurent : les Bloodscalp, les Skullsplitter et les fidèles du paria {link:zanzil-the-outcast}Zanzil{/link}, toujours en guerre les uns contre les autres.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les gobelins de {link:booty-bay}Baie-du-Butin{/link}.{/b} Marchands, courtiers et cogneurs du {link:steamwheedle-cartel}Cartel Gentepression{/link}, et les pirates des Blackwater Raiders qui boivent dans leurs tavernes.
• {b}La Voile sanglante.{/b} Des pirates rivaux qui ont débarqué sur le Rivage cruel et complotent contre le port.
• {b}Les tribus gurubashi.{/b} Les trolls Bloodscalp dans les ruines du nord-ouest, les trolls Skullsplitter dans les ruines du centre, et les fidèles de {link:zanzil-the-outcast}Zanzil{/link} sur le cap. Derrière les murs de {link:zul-gurub}Zul’Gurub{/link}, des puissances plus anciennes s'agitent encore.
• {b}Les rebelles et les déserteurs.{/b} Les rebelles du lieutenant {link:lieutenant-doren}Doren{/link} au nord, et les hommes du colonel {link:colonel-kurzen}Kurzen{/link} dans la base située à leur est.
• {b}La {link:horde}Horde{/link} à {link:grom-gol-base-camp}Grom'gol{/link}.{/b} Des orcs et des trolls {link:darkspear-trolls}Darkspear{/link} qui gardent la route de ravitaillement vers {link:stonard}Stonard{/link} et les zeppelins vers le nord.
• {b}Les chasseurs.{/b} {link:hemet-nesingwary}Hemet Nesingwary{/link} et ses compagnons, campés au bord de la rivière du nord.
• {b}Les ogres.{/b} Le clan {link:mosh-ogg-ogre-mound}Mosh'Ogg{/link} tient un tertre dans les montagnes de l'est et les ruines de Mizjah.
• {b}Les nagas, les murlocs et les géants de la mer.{/b} Ils hantent les côtes, les ruines englouties et les récifs.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}L'Empire.{/b} Pendant de longs âges, les Gurubashi régnèrent sur ces jungles depuis {link:zul-gurub}Zul’Gurub{/link}. Leurs cités de pierre s'élevaient le long des rivières et des côtes.
• {b}L'Écorcheur d'âmes.{/b} {link:hakkar}Hakkar{/link} fut appelé dans le monde par les Atal'ai. Son culte plongea l'empire dans la guerre civile, et sa défaite le laissa en ruine.
• {b}La Dispersion.{/b} Les tribus gurubashi se battirent entre elles pour ce qui restait. La {link:darkspear-trolls}tribu Darkspear{/link} fut chassée de la jungle et partit pour les îles des mers du sud.
• {b}Les gobelins.{/b} Les gobelins chassèrent les trolls d'un port à la pointe sud de la jungle et y bâtirent {link:booty-bay}Baie-du-Butin{/link}. Aucune chronique de la jungle n'en rapporte l'année.
• {b}Le temps présent.{/b} Les gens du nord sont venus toujours plus nombreux : soldats, chasseurs, mineurs et la {link:horde}Horde{/link}. Aucun d'eux n'a dompté la Vallée.]=],
		},
		{
			title = "Récits de la jungle",
			text = [=[• Chaque peuple d'{link:azeroth}Azeroth{/link}, dit-on, prétend que les eaux de la source sacrée des falaises de l'ouest ont été bénies pour les siens seuls.
• Les soldats du camp rebelle se racontent que les gobelins de {link:booty-bay}Baie-du-Butin{/link} traînent des marins ivres à bord de navires négriers et les emmènent vers des lieux que personne ne nomme.
• Une maladie appelée la fièvre de Strangleronce abat les marins du cap. Le seul remède, disent les féticheurs, est le cœur d'un singe blanc que nul ne parvient à trouver.
• {link:hemet-nesingwary}Hemet Nesingwary{/link} a écrit un livre sur ses chasses dans la jungle. Ses pages se sont un jour envolées au vent, et la jungle en cacherait encore quelques-unes.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne rapporte les années où l'empire gurubashi s'éleva, tomba ou se dispersa, ni l'année où les gobelins prirent {link:booty-bay}Baie-du-Butin{/link}.]=],
		},
	},
})

Translate("frFR", "booty-bay", {
	title = "Baie-du-Butin",
	sections = {
		{
			title = "Résumé",
			text = [=[Baie-du-Butin est le port gobelin de la pointe sud de {link:stranglethorn-vale}Strangleronce{/link}. Depuis la jungle, on y entre par un tunnel percé dans les falaises, et la ville elle-même s'accroche aux parois d'une anse profonde, cercle après cercle de maisons de bois et de passerelles autour d'un port bondé. Le baron {link:baron-revilgaz}Revilgaz{/link} la gouverne depuis le dernier étage de la taverne. Les cogneurs du {link:steamwheedle-cartel}Cartel Gentepression{/link} maintiennent la paix entre l'{link:alliance}Alliance{/link} et la {link:horde}Horde{/link}, et les pirates des {red:blackwater-raiders}Blackwater Raiders{/red} remplissent ses auberges entre deux voyages. Des navires partent de ses quais pour {link:ratchet}Ratchet{/link}, de l'autre côté de la mer. Tout peut s'acheter ici, et presque tout peut se vendre.]=],
		},
	},
})

Translate("frFR", "gurubashi-arena", {
	title = "Arène des Gurubashi",
	aliases = { "l'arène" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'Arène des Gurubashi est un grand cercle de pierre au cœur de la jungle, élevé par les trolls au temps de leur empire. Ses gradins tiennent encore debout, fendus et envahis de végétation, autour d'une piste de sable. Les trolls l'ont désertée. De temps à autre, un pirate nommé {link:short-john-mithril}Short John Mithril{/link} pose un coffre de trésor sur la piste et laisse les combattants les plus hardis de la jungle s'entretuer pour l'avoir. Ceux qui gagnent encore et encore, dit-il, peuvent se dire maîtres de l'arène.]=],
		},
	},
})

Translate("frFR", "zul-gurub", {
	title = "Zul’Gurub",
	sections = {
		{
			title = "Résumé",
			text = [=[Zul’Gurub fut la grande cité des trolls gurubashi, et c'est de là que leur empire gouvernait jadis le sud. C'est ici que les prêtres atal'ai appelèrent {link:hakkar}Hakkar{/link} l'Écorcheur d'âmes dans le monde, et ici que les tribus se levèrent pour l'abattre. La cité se trouve au nord-est de la jungle, derrière des murs que les lianes n'ont pas brisés. Ses portes sont closes. Des guerriers gurubashi et des prêtres hakkari montent encore la garde devant elles, et une grande prêtresse marche parmi eux. Ceux qui vivent aux alentours ne demandent pas ce qui se fait à l'intérieur.]=],
		},
		{
			title = "En ces jours",
			text = [=[Les {link:darkspear-trolls}Darkspear{/link} n'ont pas oublié la cité. C'est à Zul’Gurub que la tribu donna jadis le plus jeune fils du chef, {link:yenniku}Yenniku{/link}, comme l'exigeait la coutume. À présent, {link:vol-jin}Vol'jin{/link} parle des batailles à venir contre ses trolls. Depuis peu, un troll de la lointaine tribu Zandalar a été vu surveillant ses murs.]=],
		},
	},
})

Translate("frFR", "nesingwary-s-expedition", {
	title = "Expédition de Nesingwary",
	aliases = { "camp de Nesingwary" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'Expédition de Nesingwary est un camp de chasse au nord de la jungle, en amont des chantiers de la {link:venture-company}KapitalRisk{/link} sur le lac {link:lake-nazferiti}Nazfériti{/link}. Ses tentes se dressent autour d'un feu, et les trophées de la chasse sont exposés à ciel ouvert. Ici, le {link:dwarves}nain{/link} {link:hemet-nesingwary}Hemet Nesingwary{/link} et ses compagnons se sont réunis pour chasser les grands fauves de {link:stranglethorn-vale}Strangleronce{/link} : tigres, panthères et raptors, et avant tout un tigre blanc. Les chasseurs accueillent les étrangers qui savent viser juste. Ils ont peu de patience pour les autres.]=],
		},
	},
})

Translate("frFR", "rebel-camp", {
	title = "Camp rebelle",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Camp rebelle se trouve à l'extrême nord de la jungle, près de la route qui descend du {link:duskwood}Bois de la Pénombre{/link}. C'est une petite palissade de tentes et de caisses, tenue par des soldats de {link:stormwind-city}Stormwind{/link} qui suivaient jadis le colonel {link:colonel-kurzen}Kurzen{/link} et se sont retournés contre lui. Le lieutenant {link:lieutenant-doren}Doren{/link} les commande. Ils sont peu nombreux, et les hommes du colonel les surpassent en nombre bien des fois. Les gobelins de {link:booty-bay}Baie-du-Butin{/link} leur envoient des vivres, et parmi eux des mines terrestres pour garder les abords du camp. Chaque soldat ici sait qu'un seul traître pourrait tous les perdre.]=],
		},
	},
})

Translate("frFR", "kurzen-s-compound", {
	title = "Base de Kurzen",
	aliases = { "base Kurzen", "La réserve" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Base de Kurzen se trouve à l'est du {link:rebel-camp}Camp rebelle{/link}, dans les collines du nord. Elle a été bâtie par des soldats, et cela se voit. Ses clôtures, ses tours et ses piles de vivres sont disposées avec soin, et sa seule maison à étage abritait jadis le bureau de l'intendant du colonel. Des combattants de la jungle, des guérisseurs et des commandos la tiennent désormais. Sur ses arrières, une grotte s'ouvre dans la colline. Les hommes du colonel l'appellent la réserve, et c'est tout au fond que le colonel {link:colonel-kurzen}Kurzen{/link} commande en personne.]=],
		},
	},
})

Translate("frFR", "grom-gol-base-camp", {
	title = "Campement Grom'gol",
	aliases = { "Grom'gol" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Campement Grom'gol est l'avant-poste du chef de guerre sur la côte ouest de {link:stranglethorn-vale}Strangleronce{/link}. La {link:horde}Horde{/link} n'est pas venue dans la jungle pour faire la guerre à ses tribus. Elle est venue garder ouverte une ligne de ravitaillement vers {link:stonard}Stonard{/link}, sa forteresse dans les marais du nord-est. Mais les raptors chassent sur les routes, les ogres tendent des embuscades aux caravanes, et le camp a dû se battre pour chaque jour où il tient debout. Des zeppelins s'élèvent de ses tours vers {link:orgrimmar}Orgrimmar{/link} et {link:undercity}Undercity{/link}. Des émissaires {link:darkspear-trolls}Darkspear{/link} y travaillent aussi, pour une mission qui leur est propre.]=],
		},
	},
})

Translate("frFR", "ruins-of-zul-kunda", {
	title = "Ruines de Zul'Kunda",
	aliases = { "Zul'Kunda" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Ruines de Zul'Kunda se dressent sur la côte nord-ouest de la jungle, là où une cité troll regardait jadis la mer. La tribu Bloodscalp les tient désormais. Leur chef {link:gan-zulah}Gan'zulah{/link} et son féticheur, {link:nezzliok-the-dire}Nezzliok le Terrible{/link}, demeurent au plus profond des ruines, et leurs chasseurs de têtes parcourent la côte jusqu'aux Ruines de Zuuldaia. Deux tablettes gravées de vieilles légendes trolls se dressent encore parmi les pierres brisées. Ceux qui viennent les recopier s'attardent rarement.]=],
		},
	},
})

Translate("frFR", "ruins-of-zul-mamwe", {
	title = "Ruines de Zul'Mamwe",
	aliases = { "Zul'Mamwe" },
	sections = {
		{
			title = "Résumé",
			text = [=[Au milieu de la jungle, à l'est de l'{link:gurubashi-arena}Arène des Gurubashi{/link}, s'étendent les terres de la tribu Skullsplitter. Leurs villages occupent les ruines de Balia'mah, de Ziata'jai et de Zul'Mamwe, et chacun garde un tas de crânes pris à ses ennemis en guise de trophées. Les Skullsplitter font la guerre aux Bloodscalp du nord et à la mémoire des {link:darkspear-trolls}Darkspear{/link}. Leur chef est Ana'thek le Cruel, et leur féticheur, Mogh, est surnommé l'Immortel. Leurs défenses sont grandes et belles, et certains gobelins leur ont trouvé un usage qui déplairait aux acheteurs de crocs de tigre.]=],
		},
	},
})

Translate("frFR", "mizjah-ruins", {
	title = "Ruines de Mizjah",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Ruines de Mizjah se trouvent au sud-est de {link:grom-gol-base-camp}Grom'gol{/link}, de l'autre côté de la rivière. Ce fut jadis une ville troll. Désormais, une bande d'ogres s'en est emparée, et du haut de ses murs les ogres fondent sur les caravanes de ravitaillement de la {link:horde}Horde{/link}, sur la route de la jungle. Les avertissements de Grom'gol sont restés sans effet, et le commandant du camp est à bout de patience. De l'autre côté de la rivière, face aux ruines, panthères et tigresses rôdent dans les sous-bois.]=],
		},
	},
})

Translate("frFR", "mosh-ogg-ogre-mound", {
	title = "Tertre des ogres Mosh'Ogg",
	aliases = { "Mosh'Ogg", "ogres Mosh'Ogg" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Tertre des ogres Mosh'Ogg se trouve dans les montagnes de l'est de {link:stranglethorn-vale}Strangleronce{/link}, non loin au sud de {link:zul-gurub}Zul’Gurub{/link}. C'est la place forte du clan Mosh'Ogg des {link:ogres}ogres{/link} : cogneurs, bellicistes, chamans et seigneurs. Tout au fond demeurait le magi ogre {link:mai-zoth}Mai'Zoth{/link}, qui connaissait la jungle depuis le temps où les {link:darkspear-trolls}Darkspear{/link} y vivaient encore. Les Mosh'Ogg aiment aussi parier, et ils n'aiment pas perdre. Un humain qui leur avait un jour trop gagné fut chassé du tertre avec ses gains.]=],
		},
	},
})

Translate("frFR", "lake-nazferiti", {
	title = "Lac Nazfériti",
	aliases = { "Nazfériti", "Campement de la KapitalRisk" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le lac Nazfériti se trouve au nord de la jungle, et sur ses rives la {link:venture-company}KapitalRisk{/link} a bâti une base d'opérations. Ses déchiqueteuses abattent la forêt et ses géologues creusent les collines à la recherche d'étranges cristaux bleus. Le contremaître, Cozzle, garde ses plans sous clé dans sa maison. La KapitalRisk n'a pas d'amis à {link:stranglethorn-vale}Strangleronce{/link}. Les marchands de {link:booty-bay}Baie-du-Butin{/link} la détestent, le baron a lancé des agents contre elle, et la jungle elle-même semble lui résister.]=],
		},
	},
})

Translate("frFR", "crystalvein-mine", {
	title = "Mine aux cristaux",
	sections = {
		{
			title = "Résumé",
			text = [=[La Mine aux cristaux se trouve dans les collines au sud-est de {link:grom-gol-base-camp}Grom'gol{/link}. Ses parois recèlent les cristaux chantants qu'on ne trouve nulle part ailleurs qu'à {link:stranglethorn-vale}Strangleronce{/link}, et elle est infestée de basilics. Les bêtes mangent le cristal, qui durcit leur peau, si bien qu'un basilic abattu peut livrer des éclats aussi beaux que ceux tirés de la roche. {link:venture-company}La KapitalRisk{/link} ne peut entrer dans la mine à cause des basilics, et elle extrait donc le cristal des collines alentour. On dit que les éclats chantent pour ceux qui savent les entendre.]=],
		},
	},
})

Translate("frFR", "the-vile-reef", {
	title = "Le Récif infâme",
	aliases = { "Récif infâme" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Récif infâme s'étend sous les eaux de la Côte sauvage, au nord-ouest de {link:grom-gol-base-camp}Grom'gol{/link}. Il y a longtemps, un grand frisson de la terre engloutit ici une cité troll, et ses rues reposent désormais sous la mer. Les trolls ont donné son nom au lieu parce que des murlocs se sont installés dans les ruines noyées et attaquent tous ceux qui s'approchent. Parmi les ruines se dresse une tablette de pierre qui raconte l'histoire de Gri'lek, un héros de la légende troll. Les {link:darkspear-trolls}Darkspear{/link} tiennent ce récit pour sacré.]=],
		},
	},
})

Translate("frFR", "nek-mani-wellspring", {
	title = "Fontaine des Nek'mani",
	aliases = { "la Source sacrée" },
	sections = {
		{
			title = "Résumé",
			text = [=[Haut sur les falaises de la côte ouest, au sud de l'{link:gurubashi-arena}Arène des Gurubashi{/link}, se trouve une source que les érudits disent sacrée. Personne ne s'accorde sur son propriétaire. Chaque peuple d'{link:azeroth}Azeroth{/link}, disent les chamans, prétend que ses eaux ont été bénies pour lui seul, et prêtres et mystiques en débattent depuis que l'on s'en souvient. Désormais, une expédition de {link:naga}nagas{/link} est montée de la mer et s'est emparée de la source. Ce que les nagas en veulent, nul ne l'a appris.]=],
		},
	},
})

Translate("frFR", "the-cape-of-stranglethorn", {
	title = "Le cap Strangleronce",
	aliases = { "cap Strangleronce" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le cap Strangleronce est l'extrémité sud de la jungle, où la terre se resserre entre deux mers en direction de {link:booty-bay}Baie-du-Butin{/link}. De grands singes errent à Valbrume, à l'est du port. Sur la rive orientale du cap, le Rivage de cristal, se dressent les ruines d'{link:ruins-of-aboraz-and-jubuwal}Aboraz{/link} et de Jubuwal, où le paria {link:zanzil-the-outcast}Zanzil{/link} garde ses fidèles. Dans une grotte cachée au sud du cap vit un féticheur qui parle avec les esprits. Les pirates de la Voile sanglante ont débarqué sur le Rivage cruel, au sud. Le cap est le coin le plus animé de {link:stranglethorn-vale}Strangleronce{/link}, et l'un des plus dangereux.]=],
		},
	},
})

Translate("frFR", "ruins-of-aboraz-and-jubuwal", {
	title = "Ruines d'Aboraz et de Jubuwal",
	aliases = { "Ruines d'Aboraz", "Ruines de Jubuwal", "Aboraz", "Jubuwal" },
	sections = {
		{
			title = "Résumé",
			text = [=[Au nord-est de {link:booty-bay}Baie-du-Butin{/link}, sur le Rivage de cristal, se dressent deux villes trolls en ruine : Aboraz et Jubuwal. Elles sont le domaine de {link:zanzil-the-outcast}Zanzil le Paria{/link}, un féticheur chassé par sa propre tribu. Ses fidèles vivent de sa mixture et ne le remettent pas en question. Les morts marchent ici aussi. Trois joueurs de Baie-du-Butin qui ne pouvaient payer leurs dettes errent désormais dans ces ruines, maudits et ensorcelés. Parmi les serviteurs de Zanzil se trouvait jadis un jeune {link:darkspear-trolls}Darkspear{/link}, le fils perdu d'un chef.]=],
		},
	},
})

Translate("frFR", "jaguero-isle", {
	title = "Ile aux jagueros",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Ile aux jagueros se trouve au large de la côte sud-est du cap. Elle est sauvage et couverte de jungle, et ses bêtes obéissent à un grand singe appelé le roi Mukla. Des panthères rôdent sur ses rivages. Peu de marins y font escale, et ceux qui le font n'y trouvent aucun port. Depuis les plages de l'île, par temps clair, on aperçoit le Rivage cruel au nord-ouest, et les grands navires des pirates au sud-ouest. Un captif les a vus lui aussi, et il a jeté un message à la mer.]=],
		},
	},
})

Translate("frFR", "wild-shore", {
	title = "Le Rivage cruel",
	aliases = { "Base de la Voile sanglante", "le Voile cramoisi" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Rivage cruel est la côte la plus méridionale de {link:stranglethorn-vale}Strangleronce{/link}, au-delà des falaises de {link:booty-bay}Baie-du-Butin{/link}. Ici, la {red:bloodsail-buccaneers}Voile sanglante{/red} a élevé une base, qu'elle appelle son poste de commandement du sud. Au large du rivage mouillent trois de ses navires : le {i}Voile cramoisi{/i}, le {i}Courant{/i} et la {i}Chance de la demoiselle{/i}. Sous les ponts du {i}Voile cramoisi{/i}, le maître de flotte {link:fleet-master-firallon}Firallon{/link} prépare sa guerre contre Baie-du-Butin. Le rivage n'est pas un lieu pour quiconque n'arbore pas les couleurs de la Voile sanglante.]=],
		},
	},
})

Translate("frFR", "green-hills-of-stranglethorn", {
	title = "Green Hills of Stranglethorn",
	found = [=[Ses pages sont dispersées dans la jungle ; Barnil Stonepot les rassemble à l'Expédition de Nesingwary]=],
	aliases = { "The Green Hills of Stranglethorn" },
	sections = {
		{
			title = "Résumé",
			text = [=[{i}Green Hills of Stranglethorn{/i} est le livre des chasses d'{link:hemet-nesingwary}Hemet Nesingwary{/link} dans la jungle, écrit de sa propre main. Son compagnon {link:barnil-stonepot}Barnil Stonepot{/link} le relisait pour lui quand une rafale de vent dispersa ses pages à travers {link:stranglethorn-vale}Strangleronce{/link}. Le livre compte quatre chapitres. Le premier plante le décor et nomme les compagnons du chasseur. Le deuxième est plein de récits de tigres et de panthères. Le troisième raconte la première prise que sir {link:sir-s-j-erlgadin}Erlgadin{/link} et dame Rouack firent avec un fusil {link:dwarves}nain{/link}, et s'achève sur un suspense. Le quatrième est le grand final. Barnil espère le voir dans les bibliothèques du monde entier.]=],
		},
	},
})

Translate("frFR", "baron-revilgaz", {
	title = "Baron Revilgaz",
	subtitle = "Seigneur de Baie-du-Butin",
	found = [=[Baie-du-Butin, au dernier étage de la taverne de l'autre côté du port]=],
	hint = [=[Montez au sommet de la taverne qui fait face au port de Baie-du-Butin.]=],
	allegiance = "Baie-du-Butin · Cartel Gentepression",
	aliases = { "Revilgaz" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le baron Revilgaz est le seigneur gobelin de {link:booty-bay}Baie-du-Butin{/link}. Du dernier étage de la taverne, il veille sur le port, les navires, le commerce et les querelles de la ville. Les siens l'appellent le pirate le plus notoire de la côte, et nul qui le connaît n'en doute. Il est riche, fier et dangereux à contrarier. Il collectionne aussi les reliques anciennes des empires trolls, et il dépensera volontiers beaucoup du temps des autres pour en ajouter une à ses étagères.]=],
		},
		{
			title = "Importance",
			text = [=[Revilgaz est la loi de {link:booty-bay}Baie-du-Butin{/link}. La Voile sanglante sait que tant qu'il vivra, elle devra traiter avec le port selon ses conditions, et elle paierait cher pour le voir mort. Ses agents surveillent la {link:venture-company}KapitalRisk{/link}, ses amis comptent des archimages du {link:kirin-tor}Kirin Tor{/link}, et son argent atteint jusqu'aux pistes de course de {link:kalimdor}Kalimdor{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il gouverne {link:booty-bay}Baie-du-Butin{/link} et le garde ouvert à tout navire qui paie.
• Il entretient des agents tels que {link:kebok}Kebok{/link} et {link:krazek}Krazek{/link}, qui lui rapportent les rumeurs et règlent ses problèmes en silence.
• Il ordonna à Kebok de s'occuper d'un gobelin qui avait commencé à écarter les magnats des princes marchands.
• Il parraine le coureur gobelin {link:pozzik}Pozzik{/link}, et il fit chercher pour lui les plans d'un régulateur de carburant de la {link:venture-company}KapitalRisk{/link}.
• Il a déjà traité avec l'archimage {link:archmage-ansirem-runeweaver}Ansirem Runeweaver{/link} de {link:dalaran}Dalaran{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La Pierre des marées",
			hint = [=[Apportez au baron des nouvelles de l'île hantée, et suivez la piste où elle mène.]=],
			text = [=[Dans la taverne, des marins parlaient d'une île au large de la côte, hantée par des élémentaires d'eau et par le fantôme d'un gobelin délirant. {link:krazek}Krazek{/link} transmit le récit, et Revilgaz se souvint d'une légende troll qu'il avait lue autrefois : la Pierre des marées, une relique qui maudit son porteur et le fait apparaître et disparaître du monde. On disait qu'un sorcier gobelin nommé Gazban l'avait trouvée. Revilgaz ne voulait pas quitter {link:booty-bay}Baie-du-Butin{/link} pour parler lui-même avec des mages assommants, aussi envoya-t-il à {link:dalaran}Dalaran{/link} les bracelets des élémentaires. {link:archmage-ansirem-runeweaver}Ansirem{/link} trouva la trace de la malédiction, et une dague troll pour la briser. La Pierre occupe désormais une place d'honneur dans la collection du baron.]=],
		},
		{
			title = "La faveur d'un parrain",
			hint = [=[Demandez l'aide du baron au nom d'un coureur gobelin des Salines.]=],
			text = [=[On avait promis au coureur gobelin {link:pozzik}Pozzik{/link} un nouveau régulateur de carburant venu de {link:booty-bay}Baie-du-Butin{/link}, et il n'arriva jamais. Les déchiqueteuses de la {link:venture-company}KapitalRisk{/link} au lac {link:lake-nazferiti}Nazfériti{/link} utilisaient le nouveau modèle, et leur contremaître gardait ses plans sous clé. Revilgaz voulait qu'on les copie, pour Pozzik et pour ses propres notes. Il n'aime pas que ses coureurs pensent que leurs parrains les ont abandonnés.]=],
		},
	},
	mentions = {
		{ text = "L'île hantée" },
		{ text = "La Pierre des marées" },
		{ text = "Élémentaires d'eau" },
		{ text = "Analyse magique" },
		{ text = "La malédiction des marées" },
		{ text = "Parrainage gobelin" },
		{ text = "Parrainage gobelin" },
		{ text = "Parrainage gobelin" },
		{ text = "OPA hostile" },
		{ text = "Holà, amiral !" },
	},
	bonds = {
		{ id = "krazek", name = "Krazek", note = "lui rapporte les rumeurs" },
		{ id = "kebok", name = "Kebok", note = "son agent à Baie-du-Butin" },
		{ id = "archmage-ansirem-runeweaver", name = "Archimage Ansirem Runeweaver", note = "le mage qui déchiffra la malédiction" },
		{ id = "catelyn-the-blade", name = "Catelyn la Lame", note = "prêta sa dague à sa cause" },
		{ id = "fleet-master-seahorn", name = "Maître de flotte Seahorn", note = "maître de la flotte qui garde le port" },
		{ id = "fleet-master-firallon", name = "Maître de flotte Firallon", note = "veut sa mort" },
	},
})

Translate("frFR", "hemet-nesingwary", {
	title = "Hemet Nesingwary",
	subtitle = "Chasseur de grands fauves",
	found = "Expédition de Nesingwary, au nord de la jungle",
	hint = [=[Trouvez le chasseur nain dont le camp se dresse en amont du lac Nazfériti.]=],
	allegiance = "Expédition de Nesingwary · Alliance",
	aliases = { "Nesingwary", "Hemet Nesingwary Jr.", "Maître Nesingwary", "Hemet" },
	sections = {
		{
			title = "Résumé",
			text = [=[Hemet Nesingwary est un {link:dwarves}nain{/link}, un chasseur et un conteur de récits de chasse. Ses compagnons le disent héros renommé de l'{link:alliance}Alliance{/link}, et il combattit sur les champs de bataille de {link:lordaeron}Lordaeron{/link} avant de prendre le fusil pour le plaisir. Il a chassé à travers le monde entier. Il est désormais venu à {link:stranglethorn-vale}Strangleronce{/link} avec une bande de compagnons chasseurs, et une bête avant toutes l'a attiré ici : le tigre blanc, le roi {link:king-bangalash}Bangalash{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Nesingwary est célèbre, riche et bien introduit. Même les gobelins de {link:booty-bay}Baie-du-Butin{/link} prennent soin d'apprendre ce qu'il fait. Il est fier de son adresse et généreux envers quiconque peut l'égaler, quels que soient sa race ou son étendard. Il a écrit le récit de ses chasses dans la jungle, et ses compagnons espèrent le voir lu dans le monde entier.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il installa son camp au bord de la rivière du nord avec {link:barnil-stonepot}Barnil Stonepot{/link}, {link:ajeck-rouack}Ajeck Rouack{/link} et sir S. J. {link:sir-s-j-erlgadin}Erlgadin{/link}.
• Il met les nouveaux venus à l'épreuve à la chasse aux raptors, tandis qu'Ajeck les juge face aux tigres et sir Erlgadin face aux panthères.
• Il chassa les bêtes de {link:desolace}Désolace{/link} avec le {link:tauren}tauren{/link} {red:roon-wildmane}Roon Wildmane{/red}, et tous deux devinrent amis malgré la vieille inimitié de leurs peuples.
• Il commanda une caisse de munitions spéciales à un gobelin des {link:the-shimmering-flats}Salines{/link} avant de partir pour la jungle.
• Il écrivit {i}{link:green-hills-of-stranglethorn}Green Hills of Stranglethorn{/link}{/i}, le récit de ses chasses.]=],
		},
	},
	chapters = {
		{
			title = "Les maîtres de la chasse",
			hint = "Faites vos preuves face aux raptors de la jungle.",
			text = [=[Les chasseurs du camp ne partagent pas leur feu avec n'importe qui. Hemet énonce ses épreuves sans détour : d'abord les raptors, puis les races plus rapides, puis les traqueurs de la jungle, les plus difficiles de tous à pister. La dernière épreuve est une raptor appelée Tethis, qu'Hemet lui-même n'a jamais tuée. Celui qui rapporte sa serre est nommé maître de la chasse aux raptors.]=],
		},
		{
			title = "Le tigre blanc",
			hint = "Chassez la bête qui a amené Nesingwary à Strangleronce.",
			text = [=[Quand Sin'Dall, Bhag'thera et Tethis furent toutes tombées, Hemet dit la vérité sur sa venue. Ce n'était pas pour elles qu'il avait traversé la mer. Il était venu pour le roi {link:king-bangalash}Bangalash{/link}, le tigre blanc, qui l'avait renvoyé au camp en boitant plus d'une fois. Quand le tigre fut abattu, Hemet acclama le chasseur qui avait accompli ce qu'il n'avait pu faire, et le nomma compagnon de l'expédition.]=],
		},
		{
			title = "Vieux amis",
			hint = "Apportez au chasseur le présent d'un ami lointain.",
			text = [=[Des présents trouvent encore le chemin du camp par-delà la mer. Un marchand gobelin des {link:the-shimmering-flats}Salines{/link} fit suivre une caisse de munitions qu'Hemet avait payée longtemps auparavant. Un {link:tauren}tauren{/link} de {link:desolace}Désolace{/link} envoya une corne de kodo, et avec elle une invitation à chasser de nouveau ensemble. Hemet se réjouit de l'une comme de l'autre. Il est pour l'heure au fond de la jungle, mais il n'a pas oublié le pays des centaures.]=],
		},
	},
	mentions = {
		{ text = "Bienvenue dans la jungle" },
		{ text = "Maîtrise des raptors" },
		{ text = "Maîtrise des raptors" },
		{ text = "Maîtrise des raptors" },
		{ text = "Maîtrise des raptors" },
		{ text = "Chasseur de gros gibier" },
		{ text = "Hemet Nesingwary" },
		{ text = "Chasser à {link:stranglethorn-vale}Strangleronce{/link}" },
		{ text = "Enquête sur le camp" },
		{
			text = [=[Les vertes collines de {link:stranglethorn-vale}Strangleronce{/link}]=],
		},
	},
	bonds = {
		{ id = "barnil-stonepot", name = "Barnil Stonepot", note = "son compagnon et relecteur" },
		{ id = "ajeck-rouack", name = "Ajeck Rouack", note = "sa compagne, maîtresse de la chasse au tigre" },
		{ id = "sir-s-j-erlgadin", name = "Sir S. J. Erlgadin", note = "son compagnon, maître de la chasse à la panthère" },
		{ id = "king-bangalash", name = "Roi Bangalash", note = "la proie pour laquelle il est venu" },
		{ id = "roon-wildmane", name = "Roon Wildmane", note = "son ami de chasse à Désolace" },
		{ id = "krazek", name = "Krazek", note = "surveille son camp pour les gobelins" },
	},
})

Translate("frFR", "lieutenant-doren", {
	title = "Lieutenant Doren",
	subtitle = "Chef des rebelles",
	found = "Le Camp rebelle, à l'extrême nord de la jungle",
	hint = [=[Cherchez l'officier qui mène les rebelles près de la route du Bois de la Pénombre.]=],
	allegiance = "Royaume de Stormwind · Camp rebelle",
	aliases = { "Doren" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le lieutenant Doren commande les rebelles de {link:stranglethorn-vale}Strangleronce{/link}. Lui et ses soldats servaient jadis le colonel {link:colonel-kurzen}Kurzen{/link}, et ils lui étaient farouchement loyaux. Puis le colonel changea. À mesure que Kurzen sombrait dans la cruauté, la dévotion de ses hommes se mua en rage, et Doren emmena ceux qui refusaient de le suivre plus longtemps dans un camp à eux. Depuis, ils sont en guerre contre leur ancien commandant.]=],
		},
		{
			title = "Importance",
			text = [=[Doren mène une guerre qu'il ne peut gagner seul. {link:colonel-kurzen}Kurzen{/link} est un tacticien brillant, et ses hommes surpassent les rebelles en nombre bien des fois. Les rebelles survivent grâce aux vivres des gobelins, aux remèdes volés et aux secrets. Doren doit bien garder ces secrets, car un seul mot dans la mauvaise oreille pourrait mettre un couteau sous la gorge de ses soldats.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il tient le {link:rebel-camp}Camp rebelle{/link} face aux forces du colonel.
• Il renvoya le soldat {link:private-thorsen}Thorsen{/link} parmi les hommes de {link:colonel-kurzen}Kurzen{/link} comme espion.
• Il chercha les registres de Bookie {link:herod}Herod{/link}, l'intendant de Kurzen, pour apprendre comment le secret de Thorsen avait été trahi.
• Il découvrit le traître dans son propre camp.
• Il envoya un champion dans la réserve affronter le colonel en personne.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucun registre ne dit comment la compagnie de Doren en vint à servir à {link:stranglethorn-vale}Strangleronce{/link}, ni quand les rebelles rompirent avec leur colonel.]=],
		},
	},
	chapters = {
		{
			title = "Le traître du camp",
			hint = "Aidez le lieutenant à découvrir qui a trahi son espion.",
			text = [=[Trois personnes seulement connaissaient la mission de {link:private-thorsen}Thorsen{/link} : Doren, le sergent {link:sergeant-yohwa}Yohwa{/link} et Thorsen lui-même. Pourtant, les hommes de {link:colonel-kurzen}Kurzen{/link} la connaissaient aussi. Dans le coffre de Bookie {link:herod}Herod{/link} se trouvait une note boueuse qui énumérait les patrouilles de Thorsen, ses amis et ses habitudes, signée d'une seule lettre. Les horaires des patrouilles firent le reste. L'homme qui avait partagé la garde de Thorsen toute cette semaine-là était le soldat Merle. Doren l'avait cru un soldat courageux au cœur loyal. La découverte le peina, et le soulagea davantage encore.]=],
		},
		{
			title = "La chute du colonel",
			hint = "Portez l'espoir des rebelles jusque dans la réserve.",
			text = [=[Quand les combattants de la jungle du colonel furent décimés et ses forces spéciales brisées, Doren demanda l'ultime et le plus rude des exploits. Celui qui avait combattu pour les rebelles devait entrer dans la réserve, passer les défenseurs de {link:colonel-kurzen}Kurzen{/link} et affronter le colonel et ses capitaines. Doren eut peine à croire le rapport quand il arriva. Pour la première fois depuis le début de la rébellion, ses soldats pouvaient respirer plus librement.]=],
		},
	},
	mentions = {
		{ text = "Secrets de la jungle" },
		{ text = "Bookie {link:herod}Herod{/link}" },
		{ text = "L'espion démasqué !" },
		{ text = "Horaires des patrouilles" },
		{ text = "Au rapport auprès de Doren" },
		{ text = "Forces spéciales" },
		{ text = "{link:colonel-kurzen}Colonel Kurzen{/link}" },
	},
	bonds = {
		{ id = "colonel-kurzen", name = "Colonel Kurzen", note = "son ancien commandant et ennemi" },
		{ id = "sergeant-yohwa", name = "Sergent Yohwa", note = "son sergent, en qui il a confiance" },
		{ id = "private-thorsen", name = "Soldat Thorsen", note = "son espion" },
		{ id = "brother-nimetz", name = "Frère Nimetz", note = "cherche la cause de la chute de Kurzen" },
		{ id = "krazek", name = "Krazek", note = "envoie ses vivres au camp" },
	},
})

Translate("frFR", "nimboya", {
	title = "Nimboya",
	subtitle = "Émissaire des Darkspear",
	found = "Campement Grom'gol",
	hint = [=[Parlez au troll Darkspear de Grom'gol qui cherche un fils perdu de sa tribu.]=],
	allegiance = "Trolls Darkspear · Horde",
	sections = {
		{
			title = "Résumé",
			text = [=[Nimboya est un troll de la tribu {link:darkspear-trolls}Darkspear{/link}, renvoyé à {link:stranglethorn-vale}Strangleronce{/link} depuis la lointaine {link:orgrimmar}Orgrimmar{/link}. Sa tâche est grave. Selon une vieille coutume de son peuple, le plus jeune fils de son chef, {link:yenniku}Yenniku{/link}, fut donné aux trolls gurubashi de {link:zul-gurub}Zul’Gurub{/link}. Quand les Darkspear quittèrent la jungle pour suivre {link:thrall}Thrall{/link}, le garçon fut laissé derrière eux et perdu. Nimboya est venu le retrouver, vivant ou mort.]=],
		},
		{
			title = "Importance",
			text = [=[Nimboya parle au nom des {link:darkspear-trolls}Darkspear{/link} sur la terre qu'ils appelaient jadis leur foyer. Par lui, la tribu poursuit ses plus vieilles querelles et ses plus récents devoirs envers la {link:horde}Horde{/link} : la recherche de {link:yenniku}Yenniku{/link}, la guerre contre les Bloodscalp, le châtiment des {link:witherbark-trolls}Witherbark{/link} qui trahirent le chef de guerre, et le projet de {link:vol-jin}Vol'jin{/link} de conquérir l'épée {link:trol-kalar}Trol'kalar{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il traqua la tribu Bloodscalp pour obtenir des nouvelles de {link:yenniku}Yenniku{/link}.
• Il examina un grand nombre de têtes réduites, et rendit grâce quand celle du garçon ne s'y trouva pas.
• Il arracha la vérité aux têtes tranchées du chef Bloodscalp et de son féticheur à l'aide d'un chaudron bouillonnant.
• Il envoya sa pique au nord, dans les {link:the-hinterlands}Hinterlands{/link}, comme sinistre message aux {link:witherbark-trolls}trolls Witherbark{/link}.
• Il oriente les champions de la {link:horde}Horde{/link} vers {link:hammerfall}Trépas-d'Orgrim{/link} et le chasseur {link:zengu}Zengu{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Les têtes qui parlèrent",
			hint = [=[Apportez les têtes du chef Bloodscalp et de son féticheur au chaudron de Nimboya.]=],
			text = [=[Nimboya craignait que les Bloodscalp aient tué le garçon, et il jura une malédiction de six cents ans sur leur chef s'il en était ainsi. Les têtes de {link:gan-zulah}Gan'zulah{/link} et de {link:nezzliok-the-dire}Nezzliok{/link} allèrent dans son chaudron, et les morts parlèrent. Même alors ils marchandèrent, et exigèrent trophées et sang avant de répondre. Enfin, Nezzliok dit la vérité. {link:yenniku}Yenniku{/link} vivait, mais il ne s'appartenait plus. Le féticheur {link:zanzil-the-outcast}Zanzil le Paria{/link} le tenait, corps et âme.]=],
		},
		{
			title = "Sauver Yenniku",
			hint = "Ramenez chez lui le fils perdu des Darkspear.",
			text = [=[L'espoir était mince après cela, aussi petit que le plus petit des insectes, disait Nimboya. Mais {link:kin-weelay}Kin'weelay{/link} apprit des esprits où se trouvait l'Œil de l'esprit. Il fut arraché à l'{link:ogres}ogre{/link} {link:mai-zoth}Mai'Zoth{/link}, et le féticheur le refaçonna en une gemme capable de contenir une âme. Grâce à elle, {link:yenniku}Yenniku{/link} fut étourdi et son esprit arraché à l'emprise de {link:zanzil-the-outcast}Zanzil{/link}, et la gemme fut rapportée à {link:grom-gol-base-camp}Grom'gol{/link}. Nimboya avait cru sa mission sans espoir. Il promit que la tribu chanterait cet exploit et le graverait dans la pierre.]=],
		},
	},
	mentions = {
		{ text = "La chasse à {link:yenniku}Yenniku{/link}" },
		{ text = "Chasse aux têtes" },
		{ text = "Têtes du clan Bloodscalp" },
		{ text = "Parler avec {link:nezzliok-the-dire}Nezzliok{/link}" },
		{ text = "Parler avec {link:gan-zulah}Gan'zulah{/link}" },
		{ text = "Le destin de {link:yenniku}Yenniku{/link}" },
		{ text = "Sauver {link:yenniku}Yenniku{/link}" },
		{ text = "{link:scourge}Fléau{/link} des trolls" },
		{ text = "Un message sinistre" },
	},
	bonds = {
		{ id = "yenniku", name = "Yenniku", note = "le fils du chef qu'il recherche" },
