Translate("frFR", "zanzil-the-outcast", {
	title = "Zanzil le Paria",
	subtitle = "Le féticheur exilé",
	found = "Les Ruines d'Aboraz, sur le Rivage de cristal",
	hint = [=[Cherchez le féticheur paria dans les ruines au nord-est de Baie-du-Butin.]=],
	allegiance = "Ses propres fidèles",
	aliases = { "Zanzil" },
	sections = {
		{
			title = "Résumé",
			text = [=[Zanzil est un féticheur troll que sa propre tribu a chassé. Ses chefs le craignaient, et non sans raison. Il sait plier l'esprit des autres. Avec les plantes de la jungle, il brasse une mixture qui engourdit la volonté de ceux qui la boivent et fortifie leur corps, et ses fidèles des ruines d'{link:ruins-of-aboraz-and-jubuwal}Aboraz{/link} et de Jubuwal en vivent. Les morts qui errent là lui doivent peut-être aussi leur état.]=],
		},
		{
			title = "Importance",
			text = [=[L'art de Zanzil s'est répandu au-delà de la jungle. Les gobelins de {link:booty-bay}Baie-du-Butin{/link} achètent des échantillons de sa mixture, et l'un d'eux a appris à en faire une boisson forte pour ses propres manigances. Loin au nord, les espions du {link:si-7}SI:7{/link} ont appris que les trolls de Zanzil savent relever les morts avec du poison, et que ce secret est passé entre les mains de la {link:defias-brotherhood}Confrérie défias{/link}. À {link:tarren-mill}Moulin-de-Tarren{/link}, {link:serge-hinott}Serge Hinott{/link} a étudié la folie qu'amènent ses poisons.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fut exilé par sa tribu pour son pouvoir sur l'esprit d'autrui.
• Il mène ses fidèles dans les ruines d'{link:ruins-of-aboraz-and-jubuwal}Aboraz{/link} et de Jubuwal.
• Il s'empara du garçon {link:darkspear-trolls}Darkspear{/link} {link:yenniku}Yenniku{/link} et le tint corps et âme.
• On dit que ses breuvages relèvent les morts.]=],
		},
	},
	chapters = {
		{
			title = "La mixture",
			hint = "Prenez aux fidèles de Zanzil le breuvage qui les enchaîne.",
			text = [=[{link:crank-fizzlebub}Crank Fizzlebub{/link} exposa l'affaire sans détour à qui voulait l'entendre. Une mixture capable d'étouffer la volonté et d'endurcir le corps vaut très cher pour ceux qui veulent gouverner les autres. Il la paya bien, et un peu plus pour le silence.]=],
		},
		{
			title = "L'âme volée",
			hint = "Libérez le jeune Darkspear de l'emprise du féticheur.",
			text = [=[L'emprise de Zanzil sur {link:yenniku}Yenniku{/link} était si forte que seule la magie la plus puissante pouvait la briser. Les féticheurs des {link:darkspear-trolls}Darkspear{/link} tirèrent cette magie du joyau d'un {link:ogres}ogre{/link}. Quand la gemme d'âme se referma sur l'esprit de Yenniku, Zanzil perdit le plus précieux de ses serviteurs.]=],
		},
	},
	mentions = {
		{ text = "Le secret de Zanzil" },
		{ text = "Le destin de {link:yenniku}Yenniku{/link}" },
		{ text = "Sauver {link:yenniku}Yenniku{/link}" },
		{ text = "Retour à {link:booty-bay}Baie-du-Butin{/link}" },
		{ text = "La mixture de Zanzil et une bière du sot" },
		{ text = "Dettes vaudou" },
		{ text = "La tour de Klaven" },
	},
	bonds = {
		{ id = "yenniku", name = "Yenniku", note = "son serviteur" },
		{ id = "crank-fizzlebub", name = "Crank Fizzlebub", note = "achète sa mixture" },
		{ id = "nimboya", name = "Nimboya", note = "cherche à lui reprendre Yenniku" },
		{ id = "agent-kearnen", name = "Agent Kearnen", note = "découvrit la piste du poison" },
		{ id = "serge-hinott", name = "Serge Hinott", note = "soigne son poison" },
	},
})

Translate("frFR", "fleet-master-seahorn", {
